style.css:
/* Edit the hex codes (#xxxxxxx) to the colour of your liking! */

:root {
  /* Background and cards */
  --background: #f0f8ff;         /* Alice blue */
  --card: #dbe9ff;               /* Soft pale blue */
  --card-alt: #ffffff;           /* Pure white */

  /* Text colors */
  --foreground: #001f3f;         /* Navy blue for solid readability */
  --card-foreground: #003366;    /* Stronger blue text for cards */
  --card-alt-foreground: #000a14;/* Almost black for alt cards */

  /* Sidebar + popovers */
  --popover: #cce0ff;            /* Light blue */
  --popover-foreground: #001f3f; /* Navy blue text for popups */

  /* Accent colors (buttons and stuff) */
  --primary: #3399ff;            /* Bright blue */
  --primary-foreground: #ffffff; /* White text on buttons */
  --secondary: #e6f0ff;          /* Super soft blue */
  --secondary-foreground: #003366;/* Blue text for secondary things */

  /* Muted text and icons */
  --muted: #a0b4cc;              /* Dusty blue */
  --muted-foreground: #6b7b8a;   /* Slightly darker for icons/text */

  /* Accent hover + extras */
  --accent: #0074d9;             /* Vivid blue hover */
  --accent-foreground: #ffffff;  /* White text on accent */

  /* Borders and outlines */
  --border: #003366;             /* Deep blue border */
  --border-outline: #99c2ff;     /* Soft blue outline */
  --border-divider: #7aa3cc;     /* Nice mid-blue */

  /* Error colors */
  --error: #ff4d4d;              /* Bright red */
  --error-foreground: #ffffff;   /* White error text */

  /* Fun stuff */
  --brand-bg: #e0f0ff;           /* Pale brandy blue */
  --icon-primary: #005f99;       /* Good strong blue for icons */

  /* Optional transparency layers */
  --scrim: #0000003c;
}
